and title like concat('%',#{title},'%')


        and date_format(meeting_time,'%Y%m%d') >= date_format(#{params.beginTime},'%Y%m%d')


        and date_format(meeting_time,'%Y%m%d') <= date_format(#{params.endTime},'%Y%m%d')


and meeting_user = #{meetingUser}
and zw = #{zw}
and dblb = #{dblb}
and zz_name like concat('%', #{zzName}, '%')
and hyjy = #{hyjy}
and curr_order = #{currOrder}
and time_tb = #{timeTb}
and gyfwnx = #{gyfwnx}
and jyj_status = #{jyjStatus}
and id = #{id}
and team_id = #{teamId}
 and (dept_id = #{deptId} or find_in_set(#{deptId},ancestors)) 
and del_flag ='0'
 order by create_time desc

mapper.update:
update xfpt_team_meeting
TIME_TB = #{timeTb}, CURR_ORDER = #{currOrder},
where id = #{id}

mapper.select:
select t.deptId,t.schoolName,t.bzhyFlg,t.jzgmyjFlg,t.zzmdFlg,
       t.xyzzxgmsFlg,t.xgjggsFlg,t.cghtFlg,t.cpzljybgFlg,t.jzmydzjbgFlg,t.schoolType,t.cggzzjFlag,t.zjbbFlg
       from (select dept.dept_id deptId,dept.dept_name schoolName,xsm.school_Type as schoolType,
case when exists(select 1 from xfpt_team_meeting a

    a.dept_id = dept.dept_id
    and a.del_flag = 0
    and find_in_set(#{parentDeptId},a.ancestors)

        and a.id in

            #{teamMeetingIdCurr}


) then '已报备' else '未报备' end as bzhyFlg,
case when exists(select 1 from xfpt_jz_buy_opinions b

    b.dept_id = dept.dept_id
    and b.del_flag = 0
    and find_in_set(#{parentDeptId},b.ancestors)

        and b.team_meeting_id in

            #{teamMeetingIdCurr}


) then '已报备' else '未报备' end as jzgmyjFlg,
case when exists(select 1 from xfpt_org_report_disclose c

    c.dept_id = dept.dept_id
    and c.del_flag = 0
    and find_in_set(#{parentDeptId},c.ancestors)

        and c.team_meeting_id in

            #{teamMeetingIdCurr}


) then '已报备' else '未报备' end as zzmdFlg,
case when exists(select 1 from xfpt_report_mode d

    d.dept_id = dept.dept_id
    and d.del_flag = 0
