    and find_in_set(#{parentDeptId},e.ancestors)

        and e.team_id in

            #{teamMeetingIdCurr}


) then '已报备' else '未报备' end as xgjggsFlg,
case when exists(select 1 from xfpt_supplice_contract f

    f.dept_id = dept.dept_id
    and f.del_flag = 0
    and find_in_set(#{parentDeptId},f.ancestors)

        and f.team_meeting_id in

            #{teamMeetingIdCurr}


) then '已报备' else '未报备' end as cghtFlg,
case when exists(select 1 from xfpt_supplice_inspection_report g

    g.dept_id = dept.dept_id
    and g.del_flag = 0
    and find_in_set(#{parentDeptId},g.ancestors)

        and g.team_meeting_id in

            #{teamMeetingIdCurr}


) then '已报备' else '未报备' end as cpzljybgFlg,
case when exists(select 1 from xfpt_patriarch_satisfaction_summarize h

    h.dept_id = dept.dept_id
    and h.del_flag = 0
    and find_in_set(#{parentDeptId},h.ancestors)

        and h.team_meeting_id in

            #{teamMeetingIdCurr}


) then '已报备' else '未报备' end as cggzzjFlag,
case when exists(select 1 from XFPT_CGLCGZZJ cggg

    cggg.dept_id = dept.dept_id
    and cggg.del_flag = 0
    and find_in_set(#{parentDeptId},cggg.ancestors)

        and cggg.team_id in

            #{teamMeetingIdCurr}


)then '已报备' else '未报备' end as zjbbFlg,
case when exists(select 1 from XFPT_PROC_SUMMARY xps

    xps.dept_id = dept.dept_id
    and xps.del_flag = 0
    and find_in_set(#{parentDeptId},xps.ancestors)

        and xps.team_id in

