)then '已报备' else '未报备' end as jzmydzjbgFlg
from sys_dept dept left join xfpt_school_message xsm on dept.dept_id = xsm.dept_id
where dept.del_flag = 0 and find_in_set(#{parentDeptId},dept.ancestors)
order by dept.dept_id) t




                and bzhyFlg = #{bblbValue}


                and jzgmyjFlg = #{bblbValue}


